        texture2D(gm_BaseTexture, v_vTexcoord.xy + dir * (1.0/3.0 - 0.5)).xyz +
        texture2D(gm_BaseTexture, v_vTexcoord.xy + dir * (2.0/3.0 - 0.5)).xyz);
