    result_color.rgb += texture2D(gm_BaseTexture, v_blurTexCoords[5].zw).rgb*0.00895781211794; 
      
    gl_FragColor.rgb = (col * result_color.rgb ) * (1.0+result_color.a*4.0); 
    gl_FragColor.a = 1.0;
      
    
